package com.gatecraft.motorvision;
import java.text.Normalizer; import java.util.*;
public final class MotorVisionMatcherCore {
 public static final String SCHEMA="gatecraft.motorvision.matches.v1"; public static final int TOP_N=3;
 public static final class Controller {String id,brandId,brandName,family,name,revision; List<String> brandAliases=new ArrayList<String>(),aliases=new ArrayList<String>(); Set<String> identityTokens=new LinkedHashSet<String>(); String idModelPhrase="";}
 public static final class Match {public String controllerId,brandId,controllerName; public double score; public List<String> matchedFields=new ArrayList<String>(),matchedTerms=new ArrayList<String>();}
 private final List<Controller> controllers=new ArrayList<Controller>(); private final Map<String,Integer> tokenDf=new HashMap<String,Integer>(); private List<Match> last=new ArrayList<Match>(); private String lastNormalized="",dbVersion="";
 @SuppressWarnings("unchecked") public int loadIndex(String json){Object rootObj=MiniJson.parse(json);if(!(rootObj instanceof Map))throw new IllegalArgumentException("MD_INDEX root must be object");Map<String,Object> root=(Map<String,Object>)rootObj;dbVersion=str(root.get("db_version"));Map<String,Map<String,Object>> brands=new HashMap<String,Map<String,Object>>();Object bo=root.get("brands");if(bo instanceof List)for(Object x:(List<Object>)bo)if(x instanceof Map){Map<String,Object>b=(Map<String,Object>)x;brands.put(str(b.get("brand_id")),b);}Object co=root.get("controllers");if(!(co instanceof List))throw new IllegalArgumentException("MD_INDEX controllers missing");ArrayList<Controller> fresh=new ArrayList<Controller>();HashSet<String>ids=new HashSet<String>();for(Object x:(List<Object>)co){if(!(x instanceof Map))continue;Map<String,Object>m=(Map<String,Object>)x;Controller c=new Controller();c.id=str(m.get("controller_id"));c.brandId=str(m.get("brand_id"));c.family=str(m.get("family"));c.name=str(m.get("controller_name"));c.revision=str(m.get("revision"));c.aliases=strList(m.get("aliases"));Map<String,Object>b=brands.get(c.brandId);if(b!=null){c.brandName=str(b.get("brand_name"));c.brandAliases=strList(b.get("aliases"));}if(c.id.length()==0||!ids.add(c.id))throw new IllegalArgumentException("duplicate/empty controller_id: "+c.id);String idModel=c.id;if(c.brandId.length()>0&&idModel.startsWith(c.brandId+"_"))idModel=idModel.substring(c.brandId.length()+1);c.idModelPhrase=normalize(idModel.replace('_',' '));addTokens(c.identityTokens,c.idModelPhrase);addTokens(c.identityTokens,normalize(c.family));addTokens(c.identityTokens,normalize(c.name));addTokens(c.identityTokens,normalize(c.revision));for(String a:c.aliases)addTokens(c.identityTokens,normalize(a));fresh.add(c);}controllers.clear();controllers.addAll(fresh);rebuildDf();last=new ArrayList<Match>();lastNormalized="";return controllers.size();}
 private void rebuildDf(){tokenDf.clear();for(Controller c:controllers)for(String t:c.identityTokens)tokenDf.put(t,Integer.valueOf(tokenDf.containsKey(t)?tokenDf.get(t).intValue()+1:1));}
 public int size(){return controllers.size();} public String dbVersion(){return dbVersion;} public String lastNormalized(){return lastNormalized;} public List<Match>lastMatches(){return new ArrayList<Match>(last);} public String bestControllerId(){return last.isEmpty()?"":last.get(0).controllerId;} public double bestScore(){return last.isEmpty()?0.0:last.get(0).score;}
 public List<Match> identify(String input){final String q=normalize(input);lastNormalized=q;final Set<String>qTokens=tokens(q);ArrayList<Match>out=new ArrayList<Match>();for(Controller c:controllers){LinkedHashSet<String>fields=new LinkedHashSet<String>(),terms=new LinkedHashSet<String>();double s=0;s+=phraseScore(q,c.idModelPhrase,125,"controller_id",fields,terms,true);String normalizedName=normalize(c.name);s+=phraseScore(q,normalizedName,115,"controller_name",fields,terms,true);if(containsPhrase(q,normalizedName)&&tokens(normalizedName).size()>=2)s+=95.0*(tokens(normalizedName).size()-1);s+=phraseScore(q,normalize(c.family),55,"family",fields,terms,false);s+=phraseScore(q,normalize(c.revision),35,"revision",fields,terms,false);double aliasBest=0;String aliasTerm="";for(String a:c.aliases){String na=normalize(a);double v=phraseValue(q,na,95,true);if(v>aliasBest){aliasBest=v;aliasTerm=na;}}if(aliasBest>0){s+=aliasBest;fields.add("alias");if(aliasTerm.length()>0)terms.add(aliasTerm);}double brandBest=phraseValue(q,normalize(c.brandName),24,false);String brandTerm=normalize(c.brandName);for(String a:c.brandAliases){String na=normalize(a);double v=phraseValue(q,na,24,false);if(v>brandBest){brandBest=v;brandTerm=na;}}if(brandBest>0){s+=brandBest;fields.add("brand");if(brandTerm.length()>0)terms.add(brandTerm);}int n=controllers.size();for(String t:qTokens)if(c.identityTokens.contains(t)&&informative(t)){int df=tokenDf.containsKey(t)?tokenDf.get(t).intValue():n;double idf=Math.log((n+1.0)/(df+1.0));double w=4.0+Math.min(30.0,8.0*idf);if(hasDigit(t))w+=6.0;s+=w;terms.add(t);fields.add("token");}if(fields.contains("brand")&&(fields.contains("alias")||fields.contains("controller_id")||fields.contains("controller_name")))s+=12;if(s>0){Match m=new Match();m.controllerId=c.id;m.brandId=c.brandId;m.controllerName=c.name;m.score=round2(s);m.matchedFields.addAll(fields);m.matchedTerms.addAll(terms);out.add(m);}}Collections.sort(out,new Comparator<Match>(){public int compare(Match a,Match b){int k=Double.compare(b.score,a.score);return k!=0?k:a.controllerId.compareTo(b.controllerId);}});if(out.size()>TOP_N)out=new ArrayList<Match>(out.subList(0,TOP_N));last=out;return new ArrayList<Match>(last);}
 private static double phraseScore(String q,String p,double base,String f,Set<String>fs,Set<String>ts,boolean strong){double v=phraseValue(q,p,base,strong);if(v>0){fs.add(f);ts.add(p);}return v;} private static double phraseValue(String q,String p,double base,boolean strong){if(p==null||p.length()<2||q.length()==0)return 0;if(q.equals(p))return base+70.0+Math.min(24,p.length()*.55);if(containsPhrase(q,p))return base+Math.min(24,p.length()*.55);if(strong){String compact=p.replace(" ",""),qc=q.replace(" ","");if(compact.length()>=5&&qc.contains(compact))return base*.92;}return 0;} private static boolean containsPhrase(String q,String p){return(" "+q+" ").contains(" "+p+" ");} private static boolean informative(String t){return t.length()>=2&&!STOP.contains(t);} private static boolean hasDigit(String s){for(int i=0;i<s.length();i++)if(Character.isDigit(s.charAt(i)))return true;return false;} private static final Set<String>STOP=new HashSet<String>(Arrays.asList("CONTROL","CONTROLLER","UNIT","BOARD","GATE","MOTOR","FAMILY","SERIES","SYSTEM","CURRENT","PLUS","WITH","AND","THE","FOR","24V","230V")); private static void addTokens(Set<String>s,String q){s.addAll(tokens(q));} private static Set<String>tokens(String q){LinkedHashSet<String>s=new LinkedHashSet<String>();if(q==null)return s;for(String t:q.split(" "))if(t.length()>0)s.add(t);return s;} private static double round2(double d){return Math.round(d*100.0)/100.0;} private static String str(Object o){return o==null?"":String.valueOf(o);} @SuppressWarnings("unchecked")private static List<String>strList(Object o){ArrayList<String>a=new ArrayList<String>();if(o instanceof List)for(Object x:(List<Object>)o){String s=str(x);if(s.length()>0)a.add(s);}return a;}
 public static String normalize(String in){if(in==null)return"";String n=Normalizer.normalize(in,Normalizer.Form.NFD).toUpperCase(Locale.ROOT);StringBuilder b=new StringBuilder(n.length());boolean sp=true;for(int i=0;i<n.length();i++){char c=n.charAt(i);int type=Character.getType(c);if(type==Character.NON_SPACING_MARK||type==Character.COMBINING_SPACING_MARK)continue;if(Character.isLetterOrDigit(c)){b.append(c);sp=false;}else if(!sp){b.append(' ');sp=true;}}int L=b.length();while(L>0&&b.charAt(L-1)==' ')b.setLength(--L);return b.toString();}
 public String matchesJson(){StringBuilder b=new StringBuilder(512);b.append('{').append("\"schema\":").append(MiniJson.quote(SCHEMA));b.append(",\"db_version\":").append(MiniJson.quote(dbVersion));b.append(",\"normalized\":").append(MiniJson.quote(lastNormalized));b.append(",\"matches\":[");for(int i=0;i<last.size();i++){if(i>0)b.append(',');Match m=last.get(i);b.append('{');b.append("\"rank\":").append(i+1).append(",\"controller_id\":").append(MiniJson.quote(m.controllerId));b.append(",\"brand_id\":").append(MiniJson.quote(m.brandId)).append(",\"controller_name\":").append(MiniJson.quote(m.controllerName));b.append(",\"score\":").append(String.format(Locale.ROOT,"%.2f",m.score));b.append(",\"matched_fields\":");appendStrings(b,m.matchedFields);b.append(",\"matched_terms\":");appendStrings(b,m.matchedTerms);b.append('}');}return b.append("]}").toString();} private static void appendStrings(StringBuilder b,List<String>a){b.append('[');for(int i=0;i<a.size();i++){if(i>0)b.append(',');b.append(MiniJson.quote(a.get(i)));}b.append(']');}
}